SELECT symbol, open_time, close_time, open_price, high_price, low_price, close_price, volume, number_of_trades, closed, ingestion_source, created_at, updated_at FROM crypto_ai.candle WHERE interval_code='1m' AND ((symbol='EGLDUSDT' AND open_time BETWEEN '2026-10-11 20:59:00' AND '2026-10-11 21:01:00') OR (symbol='EGLDUSDT' AND open_time BETWEEN '2026-10-11 22:41:00' AND '2026-10-11 22:45:00') OR (symbol='XRPUSDT' AND open_time BETWEEN '2026-10-12 03:29:00' AND '2026-10-12 03:31:00') OR (symbol='SHIBUSDT' AND open_time BETWEEN '2026-10-12 07:14:00' AND '2026-10-12 07:16:00') OR (symbol='ACEUSDT' AND open_time BETWEEN '2026-10-12 10:04:00' AND '2026-10-12 10:06:00') OR (symbol='BTCUSDT' AND open_time BETWEEN '2026-10-11 22:42:00' AND '2026-10-11 22:44:00')) ORDER BY symbol, open_time LIMIT 40